import{_ as u,C as h,o as r,c as m,a9 as a,E as s,b as l,w as t,a as o,a8 as d,j as i}from"./chunks/framework.BOiBTRPC.js";const A=JSON.parse('{"title":"Query Plans & Optimization — Watching the Optimizer Think","description":"From a two-table SQL query to a tree of operators, then watch an optimizer rewrite it one rule at a time — predicate pushdown, column pruning, join order, and why physical plans are where the real decisions happen.","frontmatter":{"title":"Query Plans & Optimization — Watching the Optimizer Think","description":"From a two-table SQL query to a tree of operators, then watch an optimizer rewrite it one rule at a time — predicate pushdown, column pruning, join order, and why physical plans are where the real decisions happen."},"headers":[],"relativePath":"intuitions/query-plans.md","filePath":"intuitions/query-plans.md"}'),g={name:"intuitions/query-plans.md"};function y(b,e,w,f,k,E){const c=h("QueryPlanViz"),n=h("Mermaid"),p=h("QuizCard");return r(),m("div",null,[e[4]||(e[4]=a(`<h1 id="query-plans-optimization" tabindex="-1">Query Plans &amp; Optimization <a class="header-anchor" href="#query-plans-optimization" aria-label="Permalink to &quot;Query Plans &amp; Optimization&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — The same SQL can scan 3 TB in one plan and 30 GB in another, and the engine decides which before you blink. If you can&#39;t read a plan, you&#39;re guessing at performance; if you can, you can usually point at the exact node where the optimizer guessed wrong.</p></blockquote><h2 id="sql-is-a-wish-not-a-recipe" tabindex="-1">SQL is a wish, not a recipe <a class="header-anchor" href="#sql-is-a-wish-not-a-recipe" aria-label="Permalink to &quot;SQL is a wish, not a recipe&quot;">​</a></h2><p>Here is a perfectly ordinary query:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">o</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">total</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> orders o</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">JOIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> customers c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> o</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">customer_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">customer_id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> o</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">year</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2024</span></span></code></pre></div><p>Notice what you did <em>not</em> write: you didn&#39;t say which table to read first, which index to use, whether to sort before joining, or which columns to load. SQL is <strong>declarative</strong> — it describes <em>what</em> result you want, not <em>how</em> to compute it. That gap between <em>what</em> and <em>how</em> is the optimizer&#39;s entire job.</p><p>A naive execution of that query: read both tables fully, join them on customer_id, then throw away every row where year ≠ 2024, then throw away every column except name and total. It returns the right answer while reading ~100x too much data.</p><p>Watch the same query get smarter, one rule at a time:</p>`,8)),s(c),e[5]||(e[5]=a('<h2 id="what-you-just-watched-is-a-logical-plan-becoming-a-physical-plan" tabindex="-1">What you just watched is a logical plan becoming a physical plan <a class="header-anchor" href="#what-you-just-watched-is-a-logical-plan-becoming-a-physical-plan" aria-label="Permalink to &quot;What you just watched is a logical plan becoming a physical plan&quot;">​</a></h2><p>The tree you saw at step 0 is a <strong>logical plan</strong> — the query translated into relational algebra:</p><ul><li><code>σ</code> (sigma) = filter rows — the <code>WHERE</code></li><li><code>π</code> (pi) = project columns — the <code>SELECT</code> list</li><li><code>⋈</code> = join — the <code>ON</code> condition</li><li>Leaves = scans of base tables</li></ul><p>The tree is <em>correct</em> but says nothing about <em>efficient</em>. Every step after that rewrote the tree into a better one — and the final step, replacing <code>JOIN</code> with <code>BROADCAST JOIN</code>, crossed an important line: the optimizer stopped asking <em>what</em> to compute and started choosing <em>how</em> to compute it. That&#39;s the boundary between a <strong>logical plan</strong> and a <strong>physical plan</strong>.</p>',4)),(r(),l(d,null,{default:t(()=>[s(n,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20LR%0A%20%20SQL%5B%22SQL%20text%22%5D%20--%3E%20P%5B%22Parser%3Cbr%2F%3Esyntax%20tree%22%5D%0A%20%20P%20--%3E%20L%5B%22Logical%20plan%3Cbr%2F%3Ewhat%20to%20compute%22%5D%0A%20%20L%20--%3E%20RBO%5B%22Rule-based%20rewrites%3Cbr%2F%3Epushdown%20%C2%B7%20pruning%20%C2%B7%20decorrelation%22%5D%0A%20%20RBO%20--%3E%20CBO%5B%22Cost-based%20choice%3Cbr%2F%3Ejoin%20order%20%C2%B7%20join%20algorithm%20%C2%B7%20access%20path%22%5D%0A%20%20CBO%20--%3E%20PHYS%5B%22Physical%20plan%3Cbr%2F%3Ehow%20to%20compute%20it%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=a('<table tabindex="0"><thead><tr><th>Layer</th><th>Answers</th><th>Example decision</th></tr></thead><tbody><tr><td>Logical plan</td><td>What result?</td><td><code>orders ⋈ customers</code>, filtered to 2024, two columns</td></tr><tr><td>Physical plan</td><td>How, on which hardware?</td><td>Broadcast the 200-row customers; sort-merge the rest; zone-map prune the scan</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>When you open <code>EXPLAIN</code> (Postgres, BigQuery, Spark <code>explain(True)</code>), you&#39;re looking at the <em>physical</em> plan. The logical plan is what you wrote; the physical plan is what you&#39;ll pay for. The skill isn&#39;t reading SQL — it&#39;s reading the difference.</p></div><h2 id="the-two-optimizer-brains" tabindex="-1">The two optimizer brains <a class="header-anchor" href="#the-two-optimizer-brains" aria-label="Permalink to &quot;The two optimizer brains&quot;">​</a></h2><h3 id="rules-—-always-good-rewrites" tabindex="-1">Rules — always-good rewrites <a class="header-anchor" href="#rules-—-always-good-rewrites" aria-label="Permalink to &quot;Rules — always-good rewrites&quot;">​</a></h3><p>The first two steps in the viz were <strong>rule-based</strong> optimizations: transformations that are correct and (almost) always cheaper regardless of statistics.</p><p><strong>Predicate pushdown</strong> slid <code>WHERE year = 2024</code> from above the join to on top of the scan. Why it wins: a join&#39;s cost is driven by input size, and filtering early means fewer rows to shuffle, hash, and compare. The query can&#39;t get <em>worse</em> — the filter was going to run anyway.</p><p><strong>Column pruning</strong> did the same trick vertically: if the query names <code>name</code> and <code>total</code>, the scan doesn&#39;t need the other 38 columns. This is why <code>SELECT *</code> in production pipelines isn&#39;t a style issue — it defeats a free 10-100x I/O reduction.</p><p>Other rules in the same family:</p><ul><li><strong>Constant folding</strong> — <code>WHERE year = 2023 + 1</code> → <code>WHERE year = 2024</code> at plan time.</li><li><strong>Decorrelation</strong> — correlated subqueries (<code>WHERE EXISTS (SELECT ... WHERE outer.id = id)</code>) rewritten as joins so they can be optimized normally.</li><li><strong>Join simplification</strong> — <code>DISTINCT</code> or <code>LIMIT</code> on one side can shrink or eliminate joins.</li></ul><h3 id="cost-—-choices-that-depend-on-the-data" tabindex="-1">Cost — choices that depend on the data <a class="header-anchor" href="#cost-—-choices-that-depend-on-the-data" aria-label="Permalink to &quot;Cost — choices that depend on the data&quot;">​</a></h3><p>The third step was different. <em>Which join algorithm</em> isn&#39;t a rewrite — it&#39;s a bet, and the optimizer places it using a <strong>cost model</strong>: estimated row counts × per-row CPU/IO/network cost, summed over candidate plans.</p>',11)),(r(),l(d,null,{default:t(()=>[s(n,{id:"mermaid-143",class:"mermaid",graph:"flowchart%20TB%0A%20%20Q%5B%22Join%20orders%20%E2%8B%88%20customers%22%5D%20--%3E%20S%7B%22customers%20small%20enough%3Cbr%2F%3Eto%20fit%20in%20memory%3F%22%7D%0A%20%20S%20--%3E%7C%22yes%20%E2%80%94%20cost%20wins%22%7C%20B%5B%22Broadcast%20hash%20join%3Cbr%2F%3Ereplicate%20small%20side%20to%20every%20worker%3Cbr%2F%3Eno%20shuffle%22%5D%0A%20%20S%20--%3E%7C%22no%22%7C%20SMJ%5B%22Sort-merge%20join%3Cbr%2F%3Eshuffle%20both%20sides%20by%20key%3Cbr%2F%3Esort%20%C2%B7%20merge%22%5D%0A%20%20S%20--%3E%7C%22stats%20missing%20%2F%20stale%22%7C%20GUESS%5B%22Optimizer%20guesses%3Cbr%2F%3Ethis%20is%20where%20prod%20plans%20go%20wrong%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=a('<p>The classic physical-join ladder, cheapest to most expensive:</p><table tabindex="0"><thead><tr><th>Algorithm</th><th>When it wins</th><th>The catch</th></tr></thead><tbody><tr><td><strong>Broadcast hash</strong></td><td>One side fits in memory (~10 MB default in Spark, configurable)</td><td>OOM if the &quot;small&quot; side lied; replicates to every worker</td></tr><tr><td><strong>Shuffle hash</strong></td><td>Both sides big, but one fits in memory <em>per partition</em></td><td>Memory pressure on the build side</td></tr><tr><td><strong>Sort-merge</strong></td><td>Both sides large</td><td>Pays a full shuffle + sort — but robust and spillable</td></tr><tr><td><strong>Nested loop</strong></td><td>Tiny left side or non-equi joins</td><td>O(m×n) — catastrophic on real data</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">⚠️ Stale statistics = wrong physical plan</p><p>Cost-based optimization is only as good as its estimates. The number-one cause of &quot;the optimizer picked a terrible plan&quot; isn&#39;t a bug — it&#39;s <strong>missing or stale table statistics</strong>. The fix isn&#39;t a hint; it&#39;s <code>ANALYZE TABLE</code> / <code>ANALYZE</code> / updated stats. A broadcast join chosen on a table that grew from 5 MB to 5 GB is a production incident the hint system signed up for.</p></div><h2 id="join-ordering-the-problem-that-makes-optimizers-hard" tabindex="-1">Join ordering: the problem that makes optimizers hard <a class="header-anchor" href="#join-ordering-the-problem-that-makes-optimizers-hard" aria-label="Permalink to &quot;Join ordering: the problem that makes optimizers hard&quot;">​</a></h2><p>Three-way join: <code>A ⋈ B ⋈ C</code>. Associativity says <code>(A ⋈ B) ⋈ C</code> and <code>A ⋈ (B ⋈ C)</code> return the same rows — but the <em>cost</em> is wildly different. If <code>A ⋈ B</code> produces 100 rows and <code>B ⋈ C</code> produces 100 million, join order decides whether your query takes seconds or never finishes.</p><p>For N tables there are N! orderings — a 10-table join has 3.6 million candidates. No optimizer enumerates them all. Two shapes organize the search:</p><table tabindex="0"><thead><tr><th>Shape</th><th>What it looks like</th><th>Trade-off</th></tr></thead><tbody><tr><td><strong>Left-deep</strong></td><td><code>((A ⋈ B) ⋈ C) ⋈ D</code> — one input always a base table</td><td>Smaller search space, pipelined execution — most optimizers default here</td></tr><tr><td><strong>Bushy</strong></td><td><code>(A ⋈ B) ⋈ (C ⋈ D)</code> — both inputs can be joins</td><td>Finds better plans in some cases, but the space explodes — needs smarter search</td></tr></tbody></table><p>Real optimizers (Postgres, Catalyst, CockroachDB) use <strong>dynamic programming</strong> over the left-deep space for smaller joins, and fall back to <strong>greedy or genetic search</strong> above a table-count threshold. The rule of thumb you carry into production: <em>join order matters most when intermediate results are huge</em> — filters and small tables should join first because they shrink what flows upward.</p><h2 id="a-cost-model-with-actual-numbers" tabindex="-1">A cost model, with actual numbers <a class="header-anchor" href="#a-cost-model-with-actual-numbers" aria-label="Permalink to &quot;A cost model, with actual numbers&quot;">​</a></h2><p>The cost model is embarrassingly simple in principle — and the estimate errors that make it wrong are the interesting part.</p><p>Suppose <code>orders</code> has 100M rows and <code>customers</code> has 10K rows. The optimizer evaluates two physical join plans:</p><p><strong>Broadcast hash join:</strong> build a hash table on <code>customers</code> (10K entries — tiny), then stream <code>orders</code> through it.</p><ul><li>Read orders: 100M rows × read cost</li><li>Broadcast customers: 10K rows × N workers (replication cost — trivial)</li><li>Cost ≈ one full scan of orders.</li></ul><p><strong>Sort-merge join:</strong> shuffle <em>both</em> sides by <code>customer_id</code>, sort each partition, merge.</p><ul><li>Read both tables: 100M + 10K rows</li><li>Shuffle orders: 100M rows × network+serialize cost — <em>the big number</em></li><li>Sort + merge both sides.</li><li>Cost ≈ scan + <strong>a full shuffle of the large table</strong>.</li></ul><p>Broadcast wins by roughly the cost of shuffling 100M rows. Easy choice — <em>if</em> the optimizer knows customers is 10K rows. Now imagine a filter <code>WHERE c.country = &#39;US&#39;</code> on customers that reduces it to 500 rows — still broadcastable. But if stats think customers is 5 GB, the optimizer picks sort-merge and the query pays a shuffle it never needed. The cost model didn&#39;t make a math error — it made a <em>data</em> error.</p><table tabindex="0"><thead><tr><th>Statistic</th><th>Where it comes from</th><th>What goes wrong</th></tr></thead><tbody><tr><td>Row count</td><td><code>ANALYZE</code> / catalog metadata</td><td>Never refreshed after bulk load</td></tr><tr><td>NDV (distinct values)</td><td>Histogram / HyperLogLog sketch</td><td>Data drift — new keys appear</td></tr><tr><td>Column histograms</td><td><code>ANALYZE</code> with bucketing</td><td>Skewed distributions mis-estimated</td></tr><tr><td>Filter selectivity</td><td>Assumed independence of predicates</td><td>Correlated columns (city + zip) multiply wrong</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">ℹ️ Correlated predicates are the silent plan-killer</p><p>Independence assumption: <code>WHERE city = &#39;NYC&#39; AND zip = &#39;10001&#39;</code> gets selectivity(city) × selectivity(zip) — but NYC and 10001 are correlated, so the true selectivity is much higher than the estimate. The optimizer thinks the filter returns 10x fewer rows than reality → under-broadcasts, over-shuffles. Modern engines (Postgres <code>CREATE STATISTICS</code>, Spark&#39;s CBO) support <em>extended statistics</em> on correlated column groups for exactly this.</p></div><h2 id="same-idea-different-dialects" tabindex="-1">Same idea, different dialects <a class="header-anchor" href="#same-idea-different-dialects" aria-label="Permalink to &quot;Same idea, different dialects&quot;">​</a></h2><p>Every engine runs the same pipeline with different vocabulary. Mapping the names:</p><table tabindex="0"><thead><tr><th>Concept</th><th>Spark (Catalyst)</th><th>Postgres</th><th>BigQuery</th><th>Trino</th></tr></thead><tbody><tr><td>Rule-based rewrite</td><td><code>Rule[LogicalPlan]</code> batches</td><td>Rewriter</td><td>Standard optimizer rules</td><td>Optimizer rules</td></tr><tr><td>Cost model</td><td>CBO with stats</td><td>cost × page/tup</td><td>Slot-time cost model</td><td>Cost-based with stats</td></tr><tr><td>Inspect plan</td><td><code>explain(True)</code> / <code>EXPLAIN</code></td><td><code>EXPLAIN (ANALYZE)</code></td><td>Query plan graph in console</td><td><code>EXPLAIN ANALYZE</code></td></tr><tr><td>Force a join</td><td><code>broadcast()</code> hint</td><td><code>SET enable_mergejoin=off</code></td><td><code>#StandardSQL</code> execution hints (limited)</td><td><code>/*+ BROADCAST */</code>-style session props</td></tr><tr><td>Refresh stats</td><td><code>ANALYZE TABLE</code></td><td><code>ANALYZE</code></td><td>Automatic (mostly)</td><td><code>ANALYZE</code></td></tr></tbody></table><p>The <em>why</em> never changes. Reading <code>EXPLAIN</code> output in an unfamiliar engine is mostly vocabulary translation — the tree shape is always the same idea.</p><h2 id="when-the-optimizer-needs-help-—-hints-but-honestly" tabindex="-1">When the optimizer needs help — hints, but honestly <a class="header-anchor" href="#when-the-optimizer-needs-help-—-hints-but-honestly" aria-label="Permalink to &quot;When the optimizer needs help — hints, but honestly&quot;">​</a></h2><p>Every engine offers hints, and every senior treats them as a last resort. The honest order of operations:</p><ol><li><strong>Fix the stats.</strong> <code>ANALYZE</code> first, always. Most &quot;bad plan&quot; cases are stale stats wearing a bad-plan costume.</li><li><strong>Restructure the data, not the query.</strong> Cluster, partition, or index so the <em>cheap</em> plan is also the <em>correct</em> plan.</li><li><strong>Restructure the query last.</strong> Rewrite correlated subqueries as joins, break a monster CTE into stages, pre-aggregate before joining.</li><li><strong>Hint only with a rollback plan.</strong> <code>/*+ BROADCAST(x) */</code> is a promise the data won&#39;t outgrow the hint. Document it, date it, re-check it quarterly.</li></ol><div class="warning custom-block"><p class="custom-block-title">⚠️ Hints ossify</p><p>A hint that was right last year becomes a bug as data grows. <code>BROADCAST</code> on a table that crossed the memory threshold converts a slow query into a driver OOM. Stats-based plans degrade gracefully; hinted plans degrade catastrophically.</p></div><h2 id="the-plan-you-ship-vs-the-plan-that-ran" tabindex="-1">The plan you ship vs the plan that ran <a class="header-anchor" href="#the-plan-you-ship-vs-the-plan-that-ran" aria-label="Permalink to &quot;The plan you ship vs the plan that ran&quot;">​</a></h2><p>One subtlety worth knowing: the plan <code>EXPLAIN</code> shows is the plan the optimizer <em>thinks</em> it will run. Two things can change it at runtime:</p><ul><li><strong>AQE / adaptive execution</strong> — Spark 3.2+, some MPP engines — replans at shuffle boundaries using measured statistics. <code>AdaptiveSparkPlan</code> in <code>explain</code> output means the final plan is decided mid-flight.</li><li><strong>Runtime filters</strong> — Bloom-filter-style dynamic pruning injected during execution (Snowflake, BigQuery, Databricks). A join&#39;s small side builds a filter that the large side&#39;s scan checks against, pruning rows the plan never mentioned.</li></ul>',29)),(r(),l(d,null,{default:t(()=>[s(n,{id:"mermaid-555",class:"mermaid",graph:"flowchart%20LR%0A%20%20PL%5B%22Static%20plan%3Cbr%2F%3Eestimates%20only%22%5D%20--%3E%20RUN%5B%22Stage%20boundary%3Cbr%2F%3Ereal%20statistics%20collected%22%5D%0A%20%20RUN%20--%3E%20DEC%7B%22Plan%20still%3Cbr%2F%3Eoptimal%3F%22%7D%0A%20%20DEC%20--%3E%7C%22yes%22%7C%20KEEP%5B%22Continue%20original%20plan%22%5D%0A%20%20DEC%20--%3E%7C%22no%22%7C%20ADJ%5B%22Replan%3A%3Cbr%2F%3Eswitch%20join%20%C2%B7%20coalesce%20%C2%B7%20split%20skew%22%5D%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[o(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=a('<p>This is why &quot;the plan looked fine in EXPLAIN&quot; and &quot;the job was still slow&quot; aren&#39;t contradictory — the plan that ran may differ from the plan you reviewed.</p><h2 id="the-physical-layer-s-cheat-codes" tabindex="-1">The physical layer&#39;s cheat codes <a class="header-anchor" href="#the-physical-layer-s-cheat-codes" aria-label="Permalink to &quot;The physical layer&#39;s cheat codes&quot;">​</a></h2><p>Two techniques operate <em>below</em> the plan tree and routinely beat clever SQL.</p><h3 id="columnar-storage" tabindex="-1">Columnar storage <a class="header-anchor" href="#columnar-storage" aria-label="Permalink to &quot;Columnar storage&quot;">​</a></h3><p>Row storage reads every column of every row touched. <strong>Columnar storage</strong> (Parquet, ORC, BigQuery Capacitor, ClickHouse) stores each column contiguously — so a query over 3 of 100 columns reads ~3% of the file. Combine that with column pruning and you see why &quot;just add a filter&quot; can&#39;t fix a <code>SELECT *</code> pipeline: the read amplification happens at the storage layer, before the engine sees a row.</p><h3 id="zone-maps-min-max-pruning" tabindex="-1">Zone maps / min-max pruning <a class="header-anchor" href="#zone-maps-min-max-pruning" aria-label="Permalink to &quot;Zone maps / min-max pruning&quot;">​</a></h3><p>Columnar files store, per row-group or block, the <strong>min and max</strong> of each column. A filter <code>WHERE year = 2024</code> on a block whose <code>min(year) = 2019, max(year) = 2022</code> is skipped <em>without reading a single row</em>. This is called <strong>zone-map pruning</strong> (Parquet: statistics pruning; BigQuery: block pruning; Snowflake: micro-partition pruning).</p><div class="info custom-block"><p class="custom-block-title">ℹ️ Why sort order and clustering are physical, not logical</p><p>Zone maps only work if similar values land in the same block. That&#39;s why <code>CLUSTER BY</code> (BigQuery), <code>OPTIMIZE ZORDER BY</code> (Delta), sort keys (Redshift), and <code>ORDER BY</code> at write time are <em>physical</em> decisions with no logical-plan equivalent — they change which blocks a filter can skip. A query can be logically identical and physically 1000x faster.</p></div><h2 id="reading-a-plan-the-30-second-drill" tabindex="-1">Reading a plan: the 30-second drill <a class="header-anchor" href="#reading-a-plan-the-30-second-drill" aria-label="Permalink to &quot;Reading a plan: the 30-second drill&quot;">​</a></h2><p>Whatever engine you use, the ritual is the same:</p><ol><li><strong>Find the biggest number.</strong> In <code>EXPLAIN ANALYZE</code> (Postgres) or the Spark SQL UI, look for the node with the largest estimated or actual rows — that&#39;s where the time goes.</li><li><strong>Check the scan.</strong> Is it a full table scan where you expected pruning? Missing predicate pushdown or missing stats.</li><li><strong>Check the join.</strong> Sort-merge on a small table → the optimizer doesn&#39;t know it&#39;s small. Stats or a broadcast hint.</li><li><strong>Compare estimated vs actual rows.</strong> Off by 10x+ → stale stats → the entire plan above that node may be wrong.</li></ol><h3 id="a-glossary-of-physical-operators" tabindex="-1">A glossary of physical operators <a class="header-anchor" href="#a-glossary-of-physical-operators" aria-label="Permalink to &quot;A glossary of physical operators&quot;">​</a></h3><p>Whatever vocabulary your engine uses, plan nodes map to a small set of physical moves:</p><table tabindex="0"><thead><tr><th>Plan word (any engine)</th><th>What it actually does</th><th>Red flag when it appears</th></tr></thead><tbody><tr><td><code>Seq Scan</code> / <code>Table Scan</code> / <code>Scan</code></td><td>Reads the relation, possibly with pushed filters</td><td>On a table you expected to prune</td></tr><tr><td><code>Index Scan</code> / <code>Index Seek</code></td><td>Uses an index to touch only matching rows</td><td>On a huge result — index overhead per row adds up</td></tr><tr><td><code>Hash Join</code> / <code>BroadcastHashJoin</code></td><td>Builds a hash table on one side, probes with the other</td><td>Build side &gt;&gt; memory → spill or OOM</td></tr><tr><td><code>SortMergeJoin</code> / <code>Merge Join</code></td><td>Sorts both inputs on the key, merges</td><td>When either side was broadcastable</td></tr><tr><td><code>Exchange</code> / <code>Shuffle</code> / <code>Redistribute</code></td><td>Moves rows across nodes — the expensive part</td><td>More than once per query without reason</td></tr><tr><td><code>Aggregate</code> / <code>HashAggregate</code></td><td>Groups and rolls up</td><td><code>spill</code> counters — groups don&#39;t fit memory</td></tr></tbody></table><p>The same 6-ish moves show up in every <code>EXPLAIN</code> ever printed. Learn them once; they transfer everywhere.</p>',15)),(r(),l(d,null,{default:t(()=>[s(n,{id:"mermaid-702",class:"mermaid",graph:"flowchart%20TB%0A%20%20EX%5B%22EXPLAIN%20output%22%5D%20--%3E%20BIG%5B%22Largest%20estimated_rows%20%2F%20longest%20stage%22%5D%0A%20%20BIG%20--%3E%20SCAN%7B%22Scan%20reads%20more%3Cbr%2F%3Ethan%20the%20filter%20returns%3F%22%7D%0A%20%20SCAN%20--%3E%7C%22yes%22%7C%20PD%5B%22Pushdown%20missing%20or%3Cbr%2F%3Ezone%20maps%20not%20aligned%22%5D%0A%20%20SCAN%20--%3E%7C%22no%22%7C%20J%7B%22Join%20strategy%3Cbr%2F%3Emismatched%20to%20sizes%3F%22%7D%0A%20%20J%20--%3E%7C%22SMJ%20on%20small%20side%22%7C%20STATS%5B%22Stale%20stats%20%E2%86%92%3Cbr%2F%3EANALYZE%20or%20broadcast%20hint%22%5D%0A%20%20J%20--%3E%7C%22est%20vs%20actual%20diverge%22%7C%20STATS%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[o(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=i("details",{class:"details custom-block"},[i("summary",null,"The interview version"),i("p",null,[o('"Walk me through what the optimizer does with my query" = parse → logical plan → rule rewrites (pushdown, pruning) → cost-based physical plan (join order, join algorithm, access path) → execute. Then say the sentence that separates seniors: '),i("em",null,'"and the failure mode is almost always stale statistics, not a bad optimizer."')])],-1)),e[10]||(e[10]=i("h2",{id:"🧠-quiz",tabindex:"-1"},[o("🧠 Quiz "),i("a",{class:"header-anchor",href:"#🧠-quiz","aria-label":'Permalink to "🧠 Quiz"'},"​")],-1)),s(p,{questions:[{q:"Why does predicate pushdown usually help even before any statistics are consulted?",options:["It converts a filter into a join, which is always faster","Filtering rows earlier shrinks the input to every operator above it, so less data is shuffled and joined","It enables index use on the filtered column","It moves the filter to the client, offloading the server"],correct:1,explain:"Pushdown is a rule-based rewrite — correct and almost always cheaper regardless of data sizes, because smaller intermediate results reduce cost everywhere downstream."},{q:"EXPLAIN shows a sort-merge join where one input is a 50-row table. What is the most likely root cause?",options:["The query used SELECT * too many times","The join key is skewed","Missing or stale table statistics made the optimizer overestimate the small side","Sort-merge is optimal for tiny tables"],correct:2,explain:"Cost-based join choice relies on estimates. A 50-row table joining via sort-merge almost always means the optimizer thinks it is much bigger — stats are the fix, not a different query shape."},{q:"What distinguishes a physical plan from a logical plan?",options:["The physical plan chooses operators and access paths — broadcast vs sort-merge, index vs scan — while the logical plan only describes what to compute","The physical plan is written in SQL; the logical plan is algebra","The logical plan is optimized; the physical plan is not","There is no difference — they are two names for the same tree"],correct:0,explain:"Logical = what (filter, join, project). Physical = how (broadcast hash join, index scan, file pruning). EXPLAIN output shows the physical plan."},{q:"A query joins 8 tables and the optimizer times out enumerating join orders. Why is this expected?",options:["8 tables means a cartesian product","The cost model only handles 4 tables","There are millions of candidate orderings — optimizers use dynamic programming on left-deep trees and heuristics beyond a threshold","Join order does not affect cost, so enumeration is pointless"],correct:2,explain:"N-factorial orderings force real optimizers to restrict the search space. Left-deep dynamic programming plus greedy/genetic fallback is the standard compromise."},{q:"Zone-map (min-max) pruning skips a Parquet row-group for WHERE year = 2024 when…",options:["The user has permission on the year column","The file has fewer than 1000 rows","The row-group statistics show max(year) < 2024 — no row can match, so the block is never read","AQE is enabled"],correct:2,explain:"Zone maps store per-block min/max. If the filter range falls outside, the block provably contains no matches — pruning happens at the storage layer without reading data."},{q:"Why does SELECT * matter on columnar storage specifically?",options:["It makes the result non-deterministic","It changes the logical plan tree shape","It disables the query cache","Columnar reads happen per column — selecting all columns reads every byte instead of the ~3 percent a narrow projection would"],correct:3,explain:"Column pruning + columnar storage is a multiplicative win: a 3-of-100-column projection reads roughly 3 percent of the file. SELECT * forfeits it entirely."}]}),e[11]||(e[11]=a('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://howqueryengineswork.com/" target="_blank" rel="noreferrer">How Query Engines Work — Andy Grove</a> (free online; the best single book on this chapter)</li><li><a href="https://use-the-index-luke.com/" target="_blank" rel="noreferrer">Use The Index, Luke</a> — indexing and access-path intuition</li><li><a href="https://japila.pl/apache-spark-internals/" target="_blank" rel="noreferrer">Spark SQL Catalyst internals — Jacek Laskowski</a></li><li><a href="https://www.postgresql.org/docs/current/using-explain.html" target="_blank" rel="noreferrer">PostgreSQL EXPLAIN docs</a></li><li><a href="https://www.cse.iitb.ac.in/infolab/Data/Courses/CS632/Papers/Cascades-graefe.pdf" target="_blank" rel="noreferrer">Cascades Framework for Query Optimization — Goetz Graefe</a> (the architecture behind most modern CBOs)</li><li><em>Designing Data-Intensive Applications</em>, Ch. 3 — columnar storage and zone maps</li></ul>',2))])}const T=u(g,[["render",y]]);export{A as __pageData,T as default};
